import {useCallback,useEffect,useState} from 'react';
import {Archive,Download,FileUp,FolderLock,Loader2,RefreshCw,ShieldCheck} from 'lucide-react';
import {changeVaultDocumentState,downloadVaultDocument,listVaultDocuments,uploadVaultDocument,uploadVaultDocumentVersion} from '../../lib/practiceOperationsApi';

const CATEGORIES=['CONSENT','REFERRAL','PRESCRIPTION_COPY','LAB_REPORT','PROGRESS_REPORT','ASSESSMENT_ATTACHMENT','SESSION_ATTACHMENT','WORKSHEET','EXERCISE_DOCUMENT','CLIENT_UPLOADED','INVOICE','RECEIPT','IDENTITY_DOCUMENT','PROFESSIONAL_DOCUMENT','OTHER'];
const VISIBILITY=['CLIENT_VISIBLE','CARE_TEAM_SHARED','PRACTITIONER_PRIVATE','PRACTICE_ADMINISTRATIVE'];
const pretty=value=>String(value||'').replaceAll('_',' ').toLowerCase().replace(/^./,letter=>letter.toUpperCase());

export function ExternalDocumentVault({clients=[],clientId=''}){
  const [items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[open,setOpen]=useState(false),[busy,setBusy]=useState(false);
  const [category,setCategory]=useState('OTHER'),[status,setStatus]=useState(''),[form,setForm]=useState({title:'',client_id:clientId,category:'OTHER',visibility:'CARE_TEAM_SHARED'}),[file,setFile]=useState(null);
  const startNew=()=>{setForm({title:'',client_id:clientId,category:'OTHER',visibility:'CARE_TEAM_SHARED'});setFile(null);setOpen(true)};
  const close=()=>{setOpen(false);setFile(null);setForm({title:'',client_id:clientId,category:'OTHER',visibility:'CARE_TEAM_SHARED'})};
  const load=useCallback(async()=>{setState('loading');setError('');try{const data=await listVaultDocuments({clientId:clientId||undefined,category:category==='ALL'?'':category,status});setItems(data.items||[]);setState('ready')}catch(reason){setError(reason.message||'Document Vault could not be loaded.');setState('error')}},[category,clientId,status]);
  useEffect(()=>{void load()},[load]);
  async function upload(event){event.preventDefault();if(!file)return;setBusy(true);setError('');try{if(form.document_id)await uploadVaultDocumentVersion(form.document_id,file);else await uploadVaultDocument({...form,client_id:form.client_id||null,tags:[],links:[]},file);setOpen(false);setFile(null);setForm({title:'',client_id:clientId,category:'OTHER',visibility:'CARE_TEAM_SHARED'});await load()}catch(reason){setError(reason.message||'Document upload failed.')}finally{setBusy(false)}}
  async function action(id,next){try{await changeVaultDocumentState(id,next);await load()}catch(reason){setError(reason.message||'Document state could not be changed.')}}
  if(state==='loading')return <div role="status" className="grid min-h-64 place-items-center"><Loader2 className="animate-spin"/><span className="sr-only">Loading Document Vault</span></div>;
  return <section className="space-y-5">
    {!clientId&&<header className="flex flex-col gap-4 rounded-[28px] bg-slate-950 p-6 text-white sm:flex-row sm:items-end sm:justify-between sm:p-8"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-blue-300">Private practice storage</p><h2 className="mt-2 text-3xl font-bold">Document Vault</h2><p className="mt-2 max-w-2xl text-sm text-slate-300">Authorised, tenant-scoped documents using short-lived private storage access.</p></div><button onClick={startNew} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950"><FileUp className="mr-2 inline" size={17}/>Upload document</button></header>}
    {clientId&&<div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h3 className="text-xl font-bold">Documents</h3><p className="text-sm text-slate-500">Private vault records linked to this client.</p></div><button onClick={startNew} className="min-h-11 rounded-xl bg-slate-950 px-4 text-sm font-bold text-white"><FileUp className="mr-2 inline" size={17}/>Upload</button></div>}
    {error&&<div role="alert" className="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><strong>Document Vault unavailable</strong><p className="mt-1">{error}</p><button onClick={load} className="mt-3 min-h-11 rounded-xl bg-amber-900 px-4 font-semibold text-white">Retry</button></div>}
    <div className="flex flex-wrap gap-2"><select aria-label="Document category" value={category} onChange={event=>setCategory(event.target.value)} className="min-h-11 rounded-xl border bg-white px-3"><option value="ALL">All categories</option>{CATEGORIES.map(value=><option key={value}>{value}</option>)}</select><select aria-label="Document status" value={status} onChange={event=>setStatus(event.target.value)} className="min-h-11 rounded-xl border bg-white px-3"><option value="">All states</option>{['PENDING_UPLOAD','AVAILABLE','ARCHIVED','QUARANTINED','UPLOAD_FAILED'].map(value=><option key={value}>{value}</option>)}</select><button onClick={load} aria-label="Refresh documents" className="grid h-11 w-11 place-items-center rounded-xl border bg-white"><RefreshCw size={17}/></button></div>
    {state==='ready'&&!items.length?<div className="rounded-3xl border border-dashed bg-white p-10 text-center"><FolderLock className="mx-auto text-blue-700"/><h3 className="mt-3 font-bold">No documents match these filters</h3><p className="mt-1 text-sm text-slate-500">The request completed successfully; this is a confirmed empty result.</p></div>:<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{items.map(item=><article key={item.id} className="rounded-3xl border bg-white p-5"><div className="flex items-start justify-between gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><ShieldCheck size={19}/></span><span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold">{pretty(item.status)}</span></div><h3 className="mt-5 font-bold">{item.title}</h3><p className="mt-1 text-sm text-slate-500">{pretty(item.category)} · {pretty(item.visibility)} · version {item.current_version}</p><div className="mt-5 flex flex-wrap gap-2">{item.status==='AVAILABLE'&&<button onClick={()=>downloadVaultDocument(item.id)} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-slate-950 px-4 text-sm font-bold text-white"><Download size={16}/>Download</button>}{item.status==='AVAILABLE'&&<button onClick={()=>{setForm({...form,document_id:item.id,title:item.title,client_id:item.client_id||'',category:item.category,visibility:item.visibility});setOpen(true)}} className="min-h-11 rounded-xl border px-3 text-sm font-bold">New version</button>}{item.status==='AVAILABLE'&&<button onClick={()=>action(item.id,'archive')} className="grid h-11 w-11 place-items-center rounded-xl border" aria-label={`Archive ${item.title}`}><Archive size={16}/></button>}{item.status==='ARCHIVED'&&<button onClick={()=>action(item.id,'restore')} className="min-h-11 rounded-xl border px-4 text-sm font-bold">Restore</button>}</div></article>)}</div>}
    {open&&<div className="fixed inset-0 z-[80] grid place-items-center bg-slate-950/50 p-4" onClick={()=>!busy&&close()}><form onSubmit={upload} onClick={event=>event.stopPropagation()} className="w-full max-w-xl rounded-3xl bg-white p-6 shadow-2xl"><h3 className="text-xl font-bold">{form.document_id?'Upload a new version':'Upload to private vault'}</h3><p className="mt-1 text-sm text-slate-500">PDF, image, text, Word, Excel or CSV. Maximum 50 MB.</p><div className="mt-5 grid gap-4 sm:grid-cols-2">{!form.document_id&&<><label className="sm:col-span-2 text-sm font-semibold">Title<input required value={form.title} onChange={event=>setForm({...form,title:event.target.value})} className="mt-1 min-h-11 w-full rounded-xl border px-3"/></label>{!clientId&&<label className="text-sm font-semibold">Client<select value={form.client_id} onChange={event=>setForm({...form,client_id:event.target.value})} className="mt-1 min-h-11 w-full rounded-xl border px-3"><option value="">Practice document</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label>}<label className="text-sm font-semibold">Category<select value={form.category} onChange={event=>setForm({...form,category:event.target.value})} className="mt-1 min-h-11 w-full rounded-xl border px-3">{CATEGORIES.map(value=><option key={value}>{value}</option>)}</select></label><label className="text-sm font-semibold">Visibility<select value={form.visibility} onChange={event=>setForm({...form,visibility:event.target.value})} className="mt-1 min-h-11 w-full rounded-xl border px-3">{VISIBILITY.map(value=><option key={value}>{value}</option>)}</select></label></>}<label className="sm:col-span-2 text-sm font-semibold">File<input required type="file" onChange={event=>setFile(event.target.files?.[0]||null)} accept=".pdf,.jpg,.jpeg,.png,.txt,.csv,.doc,.docx,.xls,.xlsx" className="mt-1 min-h-11 w-full rounded-xl border p-2"/></label></div><div className="mt-6 flex justify-end gap-2"><button type="button" disabled={busy} onClick={close} className="min-h-11 rounded-xl border px-4 font-semibold">Cancel</button><button disabled={busy||!file} className="min-h-11 rounded-xl bg-blue-700 px-4 font-bold text-white disabled:opacity-50">{busy?'Uploading privately…':'Upload'}</button></div></form></div>}
  </section>;
}

export function ClientDocumentVault({clientId}){return <ExternalDocumentVault clientId={clientId}/>}
